cana tindak lanjut</label><textarea name="follow_up">{{$travel->draft['follow_up']}}</textarea></div><button class="btn">Simpan tindak lanjut</button></form><form method="post" action="/pangi/{{$travel->uuid}}/sync">@csrf<input type="hidden" name="draft_hash" value="{{$travel->draft_hash}}"><label class="check-line"><input type="checkbox" name="confirm" value="1" required>Saya telah meninjau draft ini untuk dikirim ke PANGI.</label><button class="btn primary" style="margin-top:18px" @disabled(!$travel->draft_hash || in_array($travel->status,['queued','locked','synced']))>{{$travel->status==='failed'?'Coba sinkron lagi':'Kirim draft ke PANGI'}}</button></form>@else<div class="empty">Buat draft setelah kunjungan selesai.</div>@endif</section><section class="card card-body" style="margin-top:20px"><h2>Log sinkronisasi</h2>@forelse($travel->logs as $l)<p>{{$l->created_at->format('d M Y H:i')}} · {{$l->status}} · HTTP {{$l->http_status??'—'}}</p><small>{{$l->error_message}}</small>@empty<p class="muted">Belum pernah disinkronkan.</p>@endforelse</section>@endsection
